    seen=[[False]*W for _ in range(H)]; out=[r[:] for r in inp]
    dirs8=[(a,b) for a in (-1,0,1) for b in (-1,0,1) if (a,b)!=(0,0)]
    for i in range(H):
        for j in range(W):
            if inp[i][j]==bg and not seen[i][j]:
                st=deque([(i,j)]); seen[i][j]=True; cells=set()
                while st:
                    a,b=st.popleft(); cells.add((a,b))
                    for da,db in dirs8:
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and not seen[na][nb] and inp[na][nb]==bg:
                            seen[na][nb]=True; st.append((na,nb))
                if not any(a==0 or a==H-1 or b==0 or b==W-1 for a,b in cells):
                    for a,b in cells: out[a][b]=4
    return out
